	env := func(kv map[string]string) func(string) string { return func(k string) string { return kv[k] } }
	if _, err := ConfigFromEnv(env(nil)); !errors.Is(err, ErrNoToken) {
		t.Errorf("no token: got %v, want ErrNoToken", err)
