	if _, err := ConfigFromEnv(env(map[string]string{"ALLOW_UNAUTHENTICATED": "1"})); !errors.Is(err, ErrNoToken) {
		t.Error(`ALLOW_UNAUTHENTICATED="1" accepted; only "true" opts out`)
