// Package store owns all SQL that is not compiled from a segment rule, and
// the migration runner.
package store

import (
	"context"
	"database/sql"
	"fmt"

	"github.com/pressly/goose/v3"
	"github.com/pressly/goose/v3/lock"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/migrations"
)

// newMigrator builds a goose provider over the embedded migrations. A
// Postgres advisory lock makes concurrent runs (compose setup, tests) wait
// for each other instead of racing.
func newMigrator(db *sql.DB) (*goose.Provider, error) {
	locker, err := lock.NewPostgresSessionLocker()
	if err != nil {
		return nil, err
	}
	return goose.NewProvider(goose.DialectPostgres, db, migrations.FS, goose.WithSessionLocker(locker))
}

// Migrate applies every pending migration. It does not close db.
func Migrate(ctx context.Context, db *sql.DB) error {
	p, err := newMigrator(db)
	if err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	if _, err := p.Up(ctx); err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	return nil
}

// Pending reports whether db lacks any embedded migration (for /readyz). It
// only reads, so it takes no lock.
func Pending(ctx context.Context, db *sql.DB) (bool, error) {
	p, err := goose.NewProvider(goose.DialectPostgres, db, migrations.FS)
	if err != nil {
		return false, err
	}
	return p.HasPending(ctx)
}
package store

import (
	"context"
	"database/sql"
	"errors"
	"regexp"
	"slices"
	"testing"

	"github.com/jackc/pgx/v5/pgconn"
	_ "github.com/jackc/pgx/v5/stdlib"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/segment"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/testdb"
)

// freshDB opens an empty, unmigrated database for one test.
func freshDB(t *testing.T) *sql.DB {
	t.Helper()
	db, err := sql.Open("pgx", testdb.Fresh(t))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { db.Close() })
	return db
}

var appTables = []string{"users", "user_events", "seed_meta", "campaigns", "campaign_revisions", "campaign_events", "llm_calls", "messages"}

func tablesPresent(t *testing.T, db *sql.DB) []string {
	t.Helper()
	var present []string
	for _, tbl := range appTables {
		var ok bool
		if err := db.QueryRow("SELECT to_regclass('public.' || $1) IS NOT NULL", tbl).Scan(&ok); err != nil {
			t.Fatal(err)
		}
		if ok {
			present = append(present, tbl)
		}
	}
	return present
}

func TestMigrateUpDownUp(t *testing.T) {
	ctx := context.Background()
	db := freshDB(t)

	pending := func(want bool) {
		t.Helper()
		if got, err := Pending(ctx, db); err != nil || got != want {
			t.Fatalf("Pending = %v, %v; want %v", got, err, want)
		}
	}
	pending(true)
	if err := Migrate(ctx, db); err != nil {
		t.Fatal(err)
	}
	pending(false)
	if got := tablesPresent(t, db); !slices.Equal(got, appTables) {
		t.Fatalf("after up: tables %v, want %v", got, appTables)
	}
	if err := Migrate(ctx, db); err != nil {
		t.Fatalf("second run is not a no-op: %v", err)
	}
	p, err := newMigrator(db)
	if err != nil {
		t.Fatal(err)
	}
	if v, err := p.GetDBVersion(ctx); err != nil || v != 2 {
		t.Fatalf("version %d, %v; want 2", v, err)
	}

	if _, err := p.DownTo(ctx, 0); err != nil {
		t.Fatalf("down: %v", err)
	}
	if got := tablesPresent(t, db); len(got) != 0 {
		t.Fatalf("after down: tables left %v", got)
	}
	pending(true)
	var domains int
	if err := db.QueryRow("SELECT count(*) FROM pg_type WHERE typtype = 'd' AND typnamespace = 'public'::regnamespace").Scan(&domains); err != nil || domains != 0 {
		t.Fatalf("after down: %d domains left (%v)", domains, err)
	}

	if err := Migrate(ctx, db); err != nil {
		t.Fatalf("up again: %v", err)
	}
}

// pgCode returns the Postgres error code of err, or "" for success.
func pgCode(err error) string {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) {
		return pgErr.Code
	}
	if err != nil {
		return "not a Postgres error: " + err.Error()
	}
	return ""
}

const (
	notNull = "23502"
	fkey    = "23503"
	unique  = "23505"
	check   = "23514"
)

func TestConstraints(t *testing.T) {
	ctx := context.Background()
	db := freshDB(t)
	if err := Migrate(ctx, db); err != nil {
		t.Fatal(err)
	}
	mustExec := func(q string, args ...any) {
		t.Helper()
		if _, err := db.Exec(q, args...); err != nil {
			t.Fatalf("setup %q: %v", q, err)
		}
	}
	const (
		user  = "00000000-0000-4000-8000-000000000001"
		campA = "00000000-0000-4000-8000-0000000000a1"
		campB = "00000000-0000-4000-8000-0000000000b1"
		revA  = "00000000-0000-4000-8000-0000000000a2"
		revB  = "00000000-0000-4000-8000-0000000000b2"
	)
	insertUser := `INSERT INTO users (id, first_name, last_name, email, phone, city, language, loyalty_tier, signup_at, consent_sms, consent_email)
		VALUES ($1, 'Ayşe', 'Yılmaz', $2, '+90 000 000 0001', $3, $4, 'gold', now(), true, true)`
	mustExec(insertUser, user, "user1@example.com", "istanbul", "tr")
	mustExec(`INSERT INTO campaigns (id, brief) VALUES ($1, 'brief a'), ($2, 'brief b')`, campA, campB)
	insertRev := `INSERT INTO campaign_revisions (id, campaign_id, n, source, segment, sms_body, email_subject, email_body)
		VALUES ($1, $2, 1, 'llm', '{}', 'sms', 'subject', 'body')`
	mustExec(insertRev, revA, campA)
	mustExec(insertRev, revB, campB)
	insertMsg := `INSERT INTO messages (campaign_id, revision_id, user_id, channel) VALUES ($1, $2, $3, $4)`
	mustExec(insertMsg, campA, revA, user, "sms")

	cases := []struct {
		name  string
		query string
		args  []any
		want  string
	}{
		{"user city outside the catalog", insertUser, []any{"00000000-0000-4000-8000-000000000002", "u2@example.com", "paris", "tr"}, check},
		{"user language outside the catalog", insertUser, []any{"00000000-0000-4000-8000-000000000003", "u3@example.com", "istanbul", "de"}, check},
		{"user without a city", insertUser, []any{"00000000-0000-4000-8000-000000000004", "u4@example.com", nil, "tr"}, notNull},
		{"duplicate email", insertUser, []any{"00000000-0000-4000-8000-000000000005", "user1@example.com", "ankara", "tr"}, unique},
		{"event type outside the catalog", `INSERT INTO user_events (user_id, type, occurred_at) VALUES ($1, 'signup', now())`, []any{user}, check},
		{"second seed_meta row", `INSERT INTO seed_meta (id, as_of, seed, user_count) VALUES (false, now(), 1, 1)`, nil, check},
		{"approved without a revision", `UPDATE campaigns SET state = 'approved' WHERE id = $1`, []any{campA}, check},
		{"half an approval", `UPDATE campaigns SET approved_by = 'marketer' WHERE id = $1`, []any{campA}, check},
		{"approving another campaign's revision",
			`UPDATE campaigns SET state = 'approved', approved_revision_id = $2, approved_by = 'marketer', approved_at = now() WHERE id = $1`,
			[]any{campA, revB}, fkey},
		{"unknown campaign state", `UPDATE campaigns SET state = 'paused' WHERE id = $1`, []any{campA}, check},
		{"revision number 0", `INSERT INTO campaign_revisions (campaign_id, n, source, segment, sms_body, email_subject, email_body) VALUES ($1, 0, 'llm', '{}', 's', 's', 'b')`, []any{campA}, check},
		{"same message twice", insertMsg, []any{campA, revA, user, "sms"}, unique},
		{"message for another campaign's revision", insertMsg, []any{campA, revB, user, "email"}, fkey},
		{"unknown channel", insertMsg, []any{campA, revA, user, "push"}, check},
		{"retrying is not a state", `UPDATE messages SET state = 'retrying'`, nil, check},
		{"sent without a provider id", `UPDATE messages SET state = 'sent', sent_at = now()`, nil, check},
		{"failed without a reason", `UPDATE messages SET state = 'failed'`, nil, check},
		{"unknown reason label", `UPDATE messages SET last_error_class = 'oops'`, nil, check},
		{"negative attempts", `UPDATE messages SET attempts = -1`, nil, check},
	}
	for _, c := range cases {
		if got := pgCode(execErr(db, c.query, c.args...)); got != c.want {
			t.Errorf("%s: got %q, want %s", c.name, got, c.want)
		}
	}

	// The valid paths still work.
	valid := []struct {
		name  string
		query string
		args  []any
	}{
		{"approve own revision", `UPDATE campaigns SET state = 'approved', approved_revision_id = $2, approved_by = 'marketer', approved_at = now() WHERE id = $1`, []any{campA, revA}},
		{"mark sent with provider id", `UPDATE messages SET state = 'sent', provider_message_id = 'p-1', sent_at = now()`, nil},
		{"seed_meta first row", `INSERT INTO seed_meta (as_of, seed, user_count) VALUES (now(), 42, 1)`, nil},
	}
	for _, v := range valid {
		if err := execErr(db, v.query, v.args...); err != nil {
			t.Errorf("%s: %v", v.name, err)
		}
	}
}

func execErr(db *sql.DB, q string, args ...any) error {
	_, err := db.Exec(q, args...)
	return err
}

// TestCatalogChecksMatchGo keeps the database CHECK lists equal to the Go
// catalog, the third copy next to the JSON Schema.
func TestCatalogChecksMatchGo(t *testing.T) {
	db := freshDB(t)
	if err := Migrate(context.Background(), db); err != nil {
		t.Fatal(err)
	}
	quoted := regexp.MustCompile(`'([^']*)'::text`)
	cases := []struct {
		table, column string
		want          []string
	}{
		{"users", "city", segment.EnumValues("city")},
		{"users", "language", segment.EnumValues("language")},
		{"users", "loyalty_tier", segment.EnumValues("loyalty_tier")},
		{"user_events", "type", segment.EventTypes()},
	}
	for _, c := range cases {
		var def string
		err := db.QueryRow(`SELECT pg_get_constraintdef(c.oid) FROM pg_constraint c
			JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
			WHERE c.conrelid = $1::regclass AND c.contype = 'c' AND a.attname = $2`, c.table, c.column).Scan(&def)
		if err != nil {
			t.Fatalf("%s.%s: %v", c.table, c.column, err)
		}
		var got []string
		for _, m := range quoted.FindAllStringSubmatch(def, -1) {
			got = append(got, m[1])
		}
		slices.Sort(got)
		want := slices.Sorted(slices.Values(c.want))
		if !slices.Equal(got, want) {
			t.Errorf("%s.%s CHECK has %v, Go catalog has %v", c.table, c.column, got, want)
		}
	}
}
package store

import (
	"context"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
)

// Querier runs one query. *pgxpool.Pool, *pgx.Conn and pgx.Tx satisfy it.
type Querier interface {
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

// SeededAt returns the seed's time anchor from seed_meta, or nil if the
// database was never seeded.
func SeededAt(ctx context.Context, q Querier) (*time.Time, error) {
	var t time.Time
	err := q.QueryRow(ctx, "SELECT as_of FROM seed_meta").Scan(&t)
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	t = t.UTC()
	return &t, nil
}
// Package testdb gives integration tests their own Postgres database, so
// packages can run in parallel without touching each other's data.
//
// Tests need TEST_DATABASE_URL (an admin connection to the test server).
// Without it they skip, unless REQUIRE_DB=1, which make test sets: then a
// missing database fails the run instead of silently skipping it.
package testdb

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"net/url"
	"os"
	"testing"
	"time"

	"github.com/jackc/pgx/v5"
	_ "github.com/jackc/pgx/v5/stdlib" // registers the "pgx" database/sql driver
)

// cloneLock serializes template clones across test packages: Postgres
// refuses to copy a template database while another session uses it.
const cloneLock int64 = 0x7e57db

// Fresh creates an empty database for the calling test, drops it when the
// test ends, and returns its connection URL.
func Fresh(t testing.TB) string {
	t.Helper()
	return create(t, "")
}

// Seed describes the data in a seeded clone, read from its seed_meta row.
type Seed struct {
	AsOf  time.Time
	Seed  int64
	Users int
}

// Seeded clones the template database that make test builds (migrated, then
// seeded at a fixed anchor) for the calling test, drops the clone when the
// test ends, and returns its URL and seed parameters. The template name is
// TEST_TEMPLATE_DB, default app_template.
func Seeded(t testing.TB) (string, Seed) {
	t.Helper()
	template := os.Getenv("TEST_TEMPLATE_DB")
	if template == "" {
		template = "app_template"
	}
	u := create(t, template)

	db, err := sql.Open("pgx", u)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	var s Seed
	if err := db.QueryRow("SELECT as_of, seed, user_count FROM seed_meta").Scan(&s.AsOf, &s.Seed, &s.Users); err != nil {
		t.Fatalf("template %s has no seed_meta row (build it with make test): %v", template, err)
	}
	s.AsOf = s.AsOf.UTC()
	return u, s
}

func create(t testing.TB, template string) string {
	t.Helper()
	base := os.Getenv("TEST_DATABASE_URL")
	if base == "" {
		if os.Getenv("REQUIRE_DB") == "1" {
			t.Fatal("REQUIRE_DB=1 but TEST_DATABASE_URL is not set")
		}
		t.Skip("TEST_DATABASE_URL is not set; run the integration tests with make test")
	}
	admin, err := sql.Open("pgx", base)
	if err != nil {
		t.Fatal(err)
	}
	b := make([]byte, 6)
	_, _ = rand.Read(b)
	name := "test_" + hex.EncodeToString(b)

	ctx := context.Background()
	conn, err := admin.Conn(ctx)
	if err != nil {
		t.Fatal(err)
	}
	stmt := "CREATE DATABASE " + name
	if template != "" {
		stmt += " TEMPLATE " + pgx.Identifier{template}.Sanitize()
		if _, err := conn.ExecContext(ctx, "SELECT pg_advisory_lock($1)", cloneLock); err != nil {
			t.Fatal(err)
		}
	}
	_, createErr := conn.ExecContext(ctx, stmt)
	if template != "" {
		_, _ = conn.ExecContext(ctx, "SELECT pg_advisory_unlock($1)", cloneLock)
	}
	conn.Close()
	if createErr != nil {
		t.Fatalf("%s: %v (the template is built by make test)", stmt, createErr)
	}

	t.Cleanup(func() {
		if _, err := admin.Exec("DROP DATABASE " + name + " WITH (FORCE)"); err != nil {
			t.Errorf("drop %s: %v", name, err)
		}
		admin.Close()
	})
	u, err := url.Parse(base)
	if err != nil {
		t.Fatal(err)
	}
	u.Path = "/" + name
	return u.String()
}
-- Campaigns, their revisions and audit trail, LLM call records, and messages.
-- State lists live in domains so each list is written once. Invariants the
-- state machine and the delivery worker rely on are enforced here too, so a
-- code bug fails loudly instead of corrupting data.

-- +goose Up
CREATE DOMAIN campaign_state AS text CHECK (VALUE IN (
    'draft', 'generating', 'in_review', 'generation_failed', 'approved',
    'sending', 'completed', 'completed_with_failures', 'rejected', 'cancelled'));

CREATE DOMAIN channel AS text CHECK (VALUE IN ('sms', 'email'));

-- "Retrying" is not a state: it is queued with attempts > 0.
CREATE DOMAIN message_state AS text CHECK (VALUE IN (
    'queued', 'sending', 'sent', 'failed', 'dead', 'skipped'));

-- Reason labels, shared by metrics and the dashboard. conn_refused is safe
-- to retry; timeout and conn_reset are ambiguous and safe only because every
-- retry carries the same idempotency key.
CREATE DOMAIN error_class AS text CHECK (VALUE IN (
    'rate_limited', 'server_error', 'timeout', 'conn_refused', 'conn_reset',
    'client_error', 'no_consent', 'cancelled'));

CREATE TABLE campaigns (
    id                   uuid           PRIMARY KEY DEFAULT gen_random_uuid(),
    brief                text           NOT NULL CHECK (char_length(brief) BETWEEN 1 AND 2000),
    state                campaign_state NOT NULL DEFAULT 'draft',
    -- Optimistic locking: every transition is UPDATE ... WHERE version = $v.
    version              integer        NOT NULL DEFAULT 0,
    current_revision_id  uuid,
    approved_revision_id uuid,
    approved_by          text,
    approved_at          timestamptz,
    -- The only source of links in copy ({{campaign_url}}). Code checks it is
    -- an https URL on an allowlisted domain.
    campaign_url         text           CHECK (char_length(campaign_url) <= 40),
    created_at           timestamptz    NOT NULL DEFAULT now(),
    updated_at           timestamptz    NOT NULL DEFAULT now(),
    -- An approval is all or nothing.
    CHECK ((approved_revision_id IS NULL) = (approved_by IS NULL)
       AND (approved_revision_id IS NULL) = (approved_at IS NULL)),
    -- Approved and later states always point at the approved revision.
    CHECK (state NOT IN ('approved', 'sending', 'completed', 'completed_with_failures')
        OR approved_revision_id IS NOT NULL)
);

-- Only valid revisions are stored: an LLM attempt or a human edit becomes a
-- revision after it passes validation (rule 7). Failed LLM attempts are kept
-- in llm_calls; rejected edits are answered with 422 and not stored.
CREATE TABLE campaign_revisions (
    id             uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    campaign_id    uuid        NOT NULL REFERENCES campaigns (id) ON DELETE CASCADE,
    n              integer     NOT NULL CHECK (n >= 1),
    source         text        NOT NULL CHECK (source IN ('llm', 'human')),
    segment        jsonb       NOT NULL,
    sms_body       text        NOT NULL,
    email_subject  text        NOT NULL,
    email_body     text        NOT NULL,
    warnings       jsonb       NOT NULL DEFAULT '[]',
    audience_total integer     CHECK (audience_total >= 0),
    sms_eligible   integer     CHECK (sms_eligible >= 0),
    email_eligible integer     CHECK (email_eligible >= 0),
    created_at     timestamptz NOT NULL DEFAULT now(),
    UNIQUE (campaign_id, n),
    -- Target of the composite foreign keys below.
    UNIQUE (id, campaign_id)
);

-- A campaign can only point at, or approve, its own revisions.
ALTER TABLE campaigns
    ADD FOREIGN KEY (current_revision_id, id) REFERENCES campaign_revisions (id, campaign_id),
    ADD FOREIGN KEY (approved_revision_id, id) REFERENCES campaign_revisions (id, campaign_id);

-- Audit trail: one row per state transition.
CREATE TABLE campaign_events (
    id          bigint         GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    campaign_id uuid           NOT NULL REFERENCES campaigns (id) ON DELETE CASCADE,
    from_state  campaign_state,
    to_state    campaign_state NOT NULL,
    actor       text           NOT NULL,
    reason      text           NOT NULL DEFAULT '',
    at          timestamptz    NOT NULL DEFAULT now()
);
CREATE INDEX campaign_events_campaign ON campaign_events (campaign_id, id);

-- One row per call to Claude, valid or not.
CREATE TABLE llm_calls (
    id                bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    campaign_id       uuid        NOT NULL REFERENCES campaigns (id) ON DELETE CASCADE,
    stage             text        NOT NULL CHECK (stage IN ('segment', 'content')),
    attempt           integer     NOT NULL CHECK (attempt >= 1),
    outcome           text        NOT NULL CHECK (outcome IN ('valid', 'invalid', 'refusal', 'max_tokens', 'transport_error')),
    error_class       error_class,
    stop_reason       text,
    model             text        NOT NULL,
    input_tokens      integer     CHECK (input_tokens >= 0),
    output_tokens     integer     CHECK (output_tokens >= 0),
    latency_ms        integer     NOT NULL CHECK (latency_ms >= 0),
    raw_output        text,
    validation_errors jsonb       NOT NULL DEFAULT '[]',
    created_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX llm_calls_campaign ON llm_calls (campaign_id, id);

-- One row per recipient per channel. The id is the idempotency key sent to
-- the provider on every attempt (rule 10).
CREATE TABLE messages (
    id                  uuid          PRIMARY KEY DEFAULT gen_random_uuid(),
    campaign_id         uuid          NOT NULL,
    revision_id         uuid          NOT NULL,
    user_id             uuid          NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    channel             channel       NOT NULL,
    state               message_state NOT NULL DEFAULT 'queued',
    attempts            integer       NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    last_error_class    error_class,
    last_error          text,
    next_attempt_at     timestamptz,
    provider_message_id text,
    sent_at             timestamptz,
    created_at          timestamptz   NOT NULL DEFAULT now(),
    updated_at          timestamptz   NOT NULL DEFAULT now(),
    -- The same person never gets the same campaign twice on one channel.
    UNIQUE (campaign_id, user_id, channel),
    -- The message belongs to a revision of its own campaign.
    FOREIGN KEY (revision_id, campaign_id) REFERENCES campaign_revisions (id, campaign_id),
    -- A sent message always has the provider's id and a send time.
    CHECK (state <> 'sent' OR (provider_message_id IS NOT NULL AND sent_at IS NOT NULL)),
    -- Failed, dead and skipped messages always say why.
    CHECK (state NOT IN ('failed', 'dead', 'skipped') OR last_error_class IS NOT NULL)
);
CREATE INDEX messages_campaign_state ON messages (campaign_id, state);
-- The dashboard's "Needs attention" panel scans unfinished messages.
CREATE INDEX messages_unfinished ON messages (state, updated_at) WHERE state IN ('queued', 'sending');

-- +goose Down
DROP TABLE messages;
DROP TABLE llm_calls;
DROP TABLE campaign_events;
ALTER TABLE campaigns DROP COLUMN current_revision_id, DROP COLUMN approved_revision_id;
DROP TABLE campaign_revisions;
DROP TABLE campaigns;
DROP DOMAIN error_class;
DROP DOMAIN message_state;
DROP DOMAIN channel;
DROP DOMAIN campaign_state;
.PHONY: up seed reseed test test-unit test-hooks lint hooks

# Throwaway test server from docker-compose.yml (profile "test", in memory).
TEST_PG := postgres://postgres:test@127.0.0.1:55432
TEMPLATE_URL := $(TEST_PG)/app_template?sslmode=disable

# The whole stack: migrate, seed (anchored at now), api.
up:
	docker compose up --build

# Load seed data into the running stack; reseed re-anchors it at now and
# wipes campaigns (docs/seed-data.md).
seed:
	docker compose run --rm seed
reseed:
	docker compose run --rm seed seed -reset

# Every test: unit, integration (against a throwaway Postgres) and hooks.
# Builds app_template once (migrated, seeded at a fixed anchor); each
# integration package clones it. No API key, no network besides local Docker.
test:
	docker compose --profile test up -d --wait postgres-test
	@trap 'docker compose --profile test rm -sf postgres-test >/dev/null 2>&1' EXIT; set -e; \
	docker compose exec -T postgres-test psql -q -U postgres -c 'DROP DATABASE IF EXISTS app_template' -c 'CREATE DATABASE app_template'; \
	DATABASE_URL='$(TEMPLATE_URL)' go run ./cmd/app migrate; \
	DATABASE_URL='$(TEMPLATE_URL)' go run ./cmd/app seed -as-of 2026-01-01T00:00:00Z -seed 42 -users 5000; \
	env -u ANTHROPIC_API_KEY TEST_DATABASE_URL='$(TEST_PG)/postgres?sslmode=disable' REQUIRE_DB=1 go test -count=1 ./...; \
	$(MAKE) -s test-hooks

# Tests that need no database (integration tests skip).
test-unit:
	env -u ANTHROPIC_API_KEY go test ./...

# Table tests for the Claude Code secret guard and the git pre-commit hook.
test-hooks:
	bash .claude/hooks/guard-secrets_test.sh
	bash .githooks/pre-commit_test.sh

lint:
	@out=$$(gofmt -l .); if [ -n "$$out" ]; then echo "gofmt needed:"; echo "$$out"; exit 1; fi
	go vet ./...

# Install the git pre-commit hook for this clone.
hooks:
	git config core.hooksPath .githooks
