				}
			}
		}
	}
}

func lowerKey(m map[string]any, key string) {
	if s, ok := m[key].(string); ok {
		m[key] = asciiLower(s)
	}
}

func asciiLower(s string) string {
	return strings.Map(func(r rune) rune {
		if 'A' <= r && r <= 'Z' {
			return r + ('a' - 'A')
		}
		return r
