	// it must not be dropped from the encoding.
	got, _ := json.Marshal(GenerateArgs{CampaignID: id})
	if string(got) != `{"campaign_id":"`+id+`","version":0}` {
		t.Errorf("version 0 encodes as %s", got)
	}
}

