	return srv
}

func TestClassifyClientTimeout(t *testing.T) {
	srv := slowServer(t)
	resp, err := post(t, freshClient(50*time.Millisecond), srv.URL)
	if err == nil {
		t.Fatal("request succeeded past the client timeout")
	}
	if got := Classify(resp, err, now); got.Class != Timeout {
		t.Errorf("client timeout: %s (%v), want timeout", got.Class, err)
	}
}

func TestClassifyContextDeadline(t *testing.T) {
	srv := slowServer(t)
	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, "POST", srv.URL, strings.NewReader("{}"))
	if err != nil {
		t.Fatal(err)
	}
	resp, err := freshClient(0).Do(req)
	if err == nil {
		resp.Body.Close()
		t.Fatal("request succeeded past the context deadline")
	}
	if got := Classify(nil, err, now); got.Class != Timeout {
		t.Errorf("context deadline: %s (%v), want timeout", got.Class, err)
	}
}

// Errors reach Classify wrapped by callers.
func TestClassifyWrappedErrors(t *testing.T) {
	cases := []struct {
		err  error
		want Class
	}{
		{context.DeadlineExceeded, Timeout},
		{fmt.Errorf("send: %w", context.DeadlineExceeded), Timeout},
		{io.EOF, ConnReset},
		{fmt.Errorf("send: %w", io.EOF), ConnReset},
		{fmt.Errorf("read: %w", io.ErrUnexpectedEOF), ConnReset},
	}
	for _, c := range cases {
		if got := Classify(nil, c.err, now); got.Class != c.want {
			t.Errorf("%v: %s, want %s", c.err, got.Class, c.want)
		}
	}
}

// ceiling is the documented upper bound: min(60s, 1s * 2^attempt).
func ceiling(attempt int) time.Duration {
	if attempt >= 6 {
		return 60 * time.Second
	}
	return time.Second << attempt
}

// Full jitter: uniform over [0, ceiling]. A fixed delay, or "equal jitter"
// that never goes below half the ceiling, fails the spread checks.
func TestBackoffFullJitter(t *testing.T) {
	rng := rand.New(rand.NewPCG(1, 2))
	for attempt := 0; attempt <= 8; attempt++ {
		top := ceiling(attempt)
		const n = 2000
		lo, hi, sum := time.Duration(math.MaxInt64), time.Duration(0), time.Duration(0)
		for range n {
			d := Backoff(attempt, rng)
			if d < 0 || d > top {
				t.Fatalf("attempt %d: delay %v outside [0, %v]", attempt, d, top)
			}
			lo, hi, sum = min(lo, d), max(hi, d), sum+d
		}
		if lo > top/10 {
			t.Errorf("attempt %d: smallest of %d delays is %v; full jitter reaches near 0", attempt, n, lo)
		}
		if hi < top*9/10 {
			t.Errorf("attempt %d: largest of %d delays is %v; full jitter reaches near %v", attempt, n, hi, top)
		}
		if mean := sum / n; mean < top*4/10 || mean > top*6/10 {
			t.Errorf("attempt %d: mean %v, want about %v", attempt, mean, top/2)
		}
	}
}

func TestBackoffLargeAttemptsStayCapped(t *testing.T) {
	rng := rand.New(rand.NewPCG(1, 2))
	for _, attempt := range []int{6, 30, 62, 63, 64, 65, 1000, math.MaxInt} {
		for range 200 {
			if d := Backoff(attempt, rng); d < 0 || d > 60*time.Second {
				t.Fatalf("attempt %d: delay %v outside [0, 60s] (shift overflow?)", attempt, d)
			}
		}
	}
}

// The random source is injected, so a seed fixes the sequence.
func TestBackoffIsDeterministic(t *testing.T) {
	a, b := rand.New(rand.NewPCG(7, 7)), rand.New(rand.NewPCG(7, 7))
	for attempt := range 10 {
		if x, y := Backoff(attempt, a), Backoff(attempt, b); x != y {
			t.Fatalf("attempt %d: %v and %v from the same seed", attempt, x, y)
		}
	}
}

package campaign

import (
	"encoding/json"
	"slices"
	"strings"
	"testing"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// allowed is the transition table from the plan, written out a second time
// on purpose: the test fails when the code's table and this one disagree.
var allowed = map[State][]State{
	Draft:            {Generating},
	Generating:       {InReview, GenerationFailed, Cancelled},
	GenerationFailed: {Generating, Cancelled},
	InReview:         {InReview, Generating, Approved, Rejected, Cancelled},
	Approved:         {Sending, Cancelled},
	Sending:          {Completed, CompletedWithFailures, Cancelled},
}

// The state names are the campaign_state domain in migration 00002.
func TestStates(t *testing.T) {
	want := []string{"draft", "generating", "in_review", "generation_failed", "approved",
		"sending", "completed", "completed_with_failures", "rejected", "cancelled"}
	var got []string
	for _, s := range States() {
		got = append(got, string(s))
	}
	slices.Sort(got)
	slices.Sort(want)
	if !slices.Equal(got, want) {
		t.Fatalf("States() = %v, want %v", got, want)
	}
}

// TestTransitionMatrix checks all 100 from/to pairs. Every pair that is not
// in the table is rejected.
func TestTransitionMatrix(t *testing.T) {
	for _, from := range States() {
		for _, to := range States() {
			want := slices.Contains(allowed[from], to)
			if got := CanTransition(from, to); got != want {
				t.Errorf("%s -> %s: allowed = %v, want %v", from, to, got, want)
			}
		}
	}
	for _, terminal := range []State{Completed, CompletedWithFailures, Rejected, Cancelled} {
		for _, to := range States() {
			if CanTransition(terminal, to) {
				t.Errorf("terminal state %s can move to %s", terminal, to)
			}
		}
	}
	if CanTransition("paused", Generating) || CanTransition(Draft, "paused") || CanTransition("", "") {
		t.Error("an unknown state is accepted")
	}
}

func schemas(t *testing.T) *schema.Set {
	t.Helper()
	set, err := schema.Load()
	if err != nil {
		t.Fatal(err)
	}
	return set
}

func decode(t *testing.T, s string) any {
	t.Helper()
	doc, err := schema.Decode(strings.NewReader(s))
	if err != nil {
		t.Fatal(err)
	}
	return doc
}

func pathCodes(list []validation.Issue) []string {
	var out []string
	for _, is := range list {
		out = append(out, is.Path+" "+is.Code)
	}
	slices.Sort(out)
	return out
}

const (
	validSegment = `{"version":1,"match":"all","conditions":[{"kind":"enum_attribute","field":"city","op":"eq","value":"istanbul"}]}`
	validContent = `{"sms":{"body":"Selam {{first_name}}, indirim burada: {{campaign_url}}"},"email":{"subject":"Sepetin seni bekliyor","body":"Selam {{first_name}}, indirim burada: {{campaign_url}}"}}`
)

func TestValidateRevisionValid(t *testing.T) {
	rev, res := ValidateRevision(schemas(t), decode(t, `{"segment":`+validSegment+`,"content":`+validContent+`}`))
	if !res.OK() {
		t.Fatalf("valid revision rejected: %+v", res.Errors)
	}
	if rev.Segment.Match != "all" || len(rev.Segment.Conditions) != 1 || rev.Segment.Conditions[0].Value != "istanbul" {
		t.Errorf("segment %+v", rev.Segment)
	}
	if rev.Content.EmailSubject != "Sepetin seni bekliyor" || !strings.Contains(rev.Content.SMSBody, "{{campaign_url}}") {
		t.Errorf("content %+v", rev.Content)
	}
	// Warnings from the content validator are kept, with the same prefix.
	if got := pathCodes(res.Warnings); !slices.Equal(got, []string{"/content/sms/body sms_multi_segment"}) {
		t.Errorf("warnings %v", got)
	}
}

// A human may type enum values in upper case. The edit is accepted, and the
// document that gets stored is the normalized one.
func TestValidateRevisionNormalizesInPlace(t *testing.T) {
	doc := decode(t, `{"segment":{"version":1,"match":"ALL","conditions":[
		{"kind":"ENUM_ATTRIBUTE","field":"CITY","op":"IN","value":["Istanbul","ANKARA"]},
		{"kind":"Event","event":"CART_ADD","within_days":30,"negate":false}]},"content":`+validContent+`}`)
	rev, res := ValidateRevision(schemas(t), doc)
	if !res.OK() {
		t.Fatalf("uppercase enums rejected: %+v", res.Errors)
	}
	if rev.Segment.Match != "all" || !slices.Equal(rev.Segment.Conditions[0].Values, []string{"istanbul", "ankara"}) {
		t.Errorf("segment %+v", rev.Segment)
	}
	stored, err := json.Marshal(doc.(map[string]any)["segment"])
	if err != nil {
		t.Fatal(err)
	}
	if strings.ToLower(string(stored)) != string(stored) {
		t.Errorf("the document to store still has upper case: %s", stored)
	}
}

// Running revision.schema.json before the two validators would report every
// problem twice. Each one must come out once, with its prefix.
func TestValidateRevisionReportsEachErrorOnce(t *testing.T) {
	doc := decode(t, `{
		"segment":{"version":1,"match":"all","conditions":[{"kind":"enum_attribute","field":"city","op":"eq","value":"paris"}]},
		"content":{"sms":{"body":"Hi {{password}}"},"email":{"subject":"s","body":"go to https://evil.example now"}}}`)
	_, res := ValidateRevision(schemas(t), doc)
	want := []string{
		"/content/email/body url_not_allowed",
		"/content/sms/body unknown_variable",
		"/segment/conditions/0/value unknown_value",
	}
	if got := pathCodes(res.Errors); !slices.Equal(got, want) {
		t.Errorf("errors %v, want %v", got, want)
	}
}

func TestValidateRevisionTopLevel(t *testing.T) {
	cases := []struct {
		name, doc string
		want      string // one error that must be present
	}{
		{"not an object", `[]`, " invalid_type"},
		{"missing segment", `{"content":` + validContent + `}`, "/segment required"},
		{"missing content", `{"segment":` + validSegment + `}`, "/content required"},
		{"extra key", `{"segment":` + validSegment + `,"content":` + validContent + `,"sql":"1=1"}`, "/sql unknown_property"},
		{"consent as an extra key", `{"segment":` + validSegment + `,"content":` + validContent + `,"consent_sms":false}`, "/consent_sms unknown_property"},
	}
	for _, c := range cases {
		_, res := ValidateRevision(schemas(t), decode(t, c.doc))
		got := pathCodes(res.Errors)
		if !slices.Contains(got, c.want) {
			t.Errorf("%s: errors %v, want %q among them", c.name, got, c.want)
		}
		if slices.Compact(slices.Clone(got)); len(slices.Compact(slices.Clone(got))) != len(got) {
			t.Errorf("%s: an error is reported twice: %v", c.name, got)
		}
	}
}

