package campaign

import (
	"encoding/json"
	"slices"
	"strings"
	"testing"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/schema"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/validation"
)

// allowed is the transition table from the plan, written out a second time
// on purpose: the test fails when the code's table and this one disagree.
var allowed = map[State][]State{
	Draft:            {Generating},
	Generating:       {InReview, GenerationFailed, Cancelled},
	GenerationFailed: {Generating, Cancelled},
	InReview:         {InReview, Generating, Approved, Rejected, Cancelled},
	Approved:         {Sending, Cancelled},
	Sending:          {Completed, CompletedWithFailures, Cancelled},
}

// The state names are the campaign_state domain in migration 00002.
func TestStates(t *testing.T) {
	want := []string{"draft", "generating", "in_review", "generation_failed", "approved",
		"sending", "completed", "completed_with_failures", "rejected", "cancelled"}
	var got []string
	for _, s := range States() {
		got = append(got, string(s))
	}
	slices.Sort(got)
	slices.Sort(want)
	if !slices.Equal(got, want) {
		t.Fatalf("States() = %v, want %v", got, want)
	}
}

// TestTransitionMatrix checks all 100 from/to pairs. Every pair that is not
// in the table is rejected.
func TestTransitionMatrix(t *testing.T) {
	for _, from := range States() {
		for _, to := range States() {
			want := slices.Contains(allowed[from], to)
			if got := CanTransition(from, to); got != want {
				t.Errorf("%s -> %s: allowed = %v, want %v", from, to, got, want)
			}
		}
	}
	for _, terminal := range []State{Completed, CompletedWithFailures, Rejected, Cancelled} {
		for _, to := range States() {
			if CanTransition(terminal, to) {
				t.Errorf("terminal state %s can move to %s", terminal, to)
			}
		}
	}
	if CanTransition("paused", Generating) || CanTransition(Draft, "paused") || CanTransition("", "") {
		t.Error("an unknown state is accepted")
	}
}

func schemas(t *testing.T) *schema.Set {
	t.Helper()
	set, err := schema.Load()
	if err != nil {
		t.Fatal(err)
	}
	return set
}

func decode(t *testing.T, s string) any {
	t.Helper()
	doc, err := schema.Decode(strings.NewReader(s))
	if err != nil {
		t.Fatal(err)
	}
	return doc
}

func pathCodes(list []validation.Issue) []string {
	var out []string
	for _, is := range list {
		out = append(out, is.Path+" "+is.Code)
	}
	slices.Sort(out)
	return out
}

const (
	validSegment = `{"version":1,"match":"all","conditions":[{"kind":"enum_attribute","field":"city","op":"eq","value":"istanbul"}]}`
	validContent = `{"sms":{"body":"Selam {{first_name}}, indirim burada: {{campaign_url}}"},"email":{"subject":"Sepetin seni bekliyor","body":"Selam {{first_name}}, indirim burada: {{campaign_url}}"}}`
)

func TestValidateRevisionValid(t *testing.T) {
	rev, res := ValidateRevision(schemas(t), decode(t, `{"segment":`+validSegment+`,"content":`+validContent+`}`))
	if !res.OK() {
		t.Fatalf("valid revision rejected: %+v", res.Errors)
	}
	if rev.Segment.Match != "all" || len(rev.Segment.Conditions) != 1 || rev.Segment.Conditions[0].Value != "istanbul" {
		t.Errorf("segment %+v", rev.Segment)
	}
	if rev.Content.EmailSubject != "Sepetin seni bekliyor" || !strings.Contains(rev.Content.SMSBody, "{{campaign_url}}") {
		t.Errorf("content %+v", rev.Content)
	}
	// Warnings from the content validator are kept, with the same prefix.
	if got := pathCodes(res.Warnings); !slices.Equal(got, []string{"/content/sms/body sms_multi_segment"}) {
		t.Errorf("warnings %v", got)
	}
}

// A human may type enum values in upper case. The edit is accepted, and the
// document that gets stored is the normalized one.
func TestValidateRevisionNormalizesInPlace(t *testing.T) {
	doc := decode(t, `{"segment":{"version":1,"match":"ALL","conditions":[
		{"kind":"ENUM_ATTRIBUTE","field":"CITY","op":"IN","value":["Istanbul","ANKARA"]},
		{"kind":"Event","event":"CART_ADD","within_days":30,"negate":false}]},"content":`+validContent+`}`)
	rev, res := ValidateRevision(schemas(t), doc)
	if !res.OK() {
		t.Fatalf("uppercase enums rejected: %+v", res.Errors)
	}
	if rev.Segment.Match != "all" || !slices.Equal(rev.Segment.Conditions[0].Values, []string{"istanbul", "ankara"}) {
		t.Errorf("segment %+v", rev.Segment)
	}
	stored, err := json.Marshal(doc.(map[string]any)["segment"])
	if err != nil {
		t.Fatal(err)
	}
	if strings.ToLower(string(stored)) != string(stored) {
		t.Errorf("the document to store still has upper case: %s", stored)
	}
}

// Running revision.schema.json before the two validators would report every
// problem twice. Each one must come out once, with its prefix.
func TestValidateRevisionReportsEachErrorOnce(t *testing.T) {
	doc := decode(t, `{
		"segment":{"version":1,"match":"all","conditions":[{"kind":"enum_attribute","field":"city","op":"eq","value":"paris"}]},
		"content":{"sms":{"body":"Hi {{password}}"},"email":{"subject":"s","body":"go to https://evil.example now"}}}`)
	_, res := ValidateRevision(schemas(t), doc)
	want := []string{
		"/content/email/body url_not_allowed",
		"/content/sms/body unknown_variable",
		"/segment/conditions/0/value unknown_value",
	}
	if got := pathCodes(res.Errors); !slices.Equal(got, want) {
		t.Errorf("errors %v, want %v", got, want)
	}
}

func TestValidateRevisionTopLevel(t *testing.T) {
	cases := []struct {
		name, doc string
		want      string // one error that must be present
	}{
		{"not an object", `[]`, " invalid_type"},
		{"missing segment", `{"content":` + validContent + `}`, "/segment required"},
		{"missing content", `{"segment":` + validSegment + `}`, "/content required"},
		{"extra key", `{"segment":` + validSegment + `,"content":` + validContent + `,"sql":"1=1"}`, "/sql unknown_property"},
		{"consent as an extra key", `{"segment":` + validSegment + `,"content":` + validContent + `,"consent_sms":false}`, "/consent_sms unknown_property"},
	}
	for _, c := range cases {
		_, res := ValidateRevision(schemas(t), decode(t, c.doc))
		got := pathCodes(res.Errors)
		if !slices.Contains(got, c.want) {
			t.Errorf("%s: errors %v, want %q among them", c.name, got, c.want)
		}
		if slices.Compact(slices.Clone(got)); len(slices.Compact(slices.Clone(got))) != len(got) {
			t.Errorf("%s: an error is reported twice: %v", c.name, got)
		}
	}
}

package campaign

import (
	"context"
	"errors"
	"slices"
	"sync"
	"testing"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/testdb"
)

func testPool(t *testing.T) *pgxpool.Pool {
	t.Helper()
	url, _ := testdb.Seeded(t)
	p, err := pgxpool.New(context.Background(), url)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(p.Close)
	return p
}

// insertCampaign creates a campaign in the given state and version. It has a
// revision and a full approval in every state, so the table's CHECKs accept
// any state and the test exercises only the state machine.
func insertCampaign(t *testing.T, p *pgxpool.Pool, state State, version int) string {
	t.Helper()
	ctx := context.Background()
	var id, rev string
	if err := p.QueryRow(ctx, `INSERT INTO campaigns (brief, campaign_url) VALUES ('brief', 'https://shop.example/k') RETURNING id::text`).Scan(&id); err != nil {
		t.Fatal(err)
	}
	if err := p.QueryRow(ctx, `INSERT INTO campaign_revisions (campaign_id, n, source, segment, sms_body, email_subject, email_body)
		VALUES ($1, 1, 'llm', '{}', 'sms', 'subject', 'body') RETURNING id::text`, id).Scan(&rev); err != nil {
		t.Fatal(err)
	}
	if _, err := p.Exec(ctx, `UPDATE campaigns SET state = $2, version = $3, current_revision_id = $4,
		approved_revision_id = $4, approved_by = 'fixture', approved_at = now() WHERE id = $1`, id, string(state), version, rev); err != nil {
		t.Fatal(err)
	}
	return id
}

type row struct {
	State   State
	Version int
	Events  []event
}

type event struct{ From, To, Actor, Reason string }

func load(t *testing.T, p *pgxpool.Pool, id string) row {
	t.Helper()
	ctx := context.Background()
	var r row
	if err := p.QueryRow(ctx, `SELECT state, version FROM campaigns WHERE id = $1`, id).Scan(&r.State, &r.Version); err != nil {
		t.Fatal(err)
	}
	rows, err := p.Query(ctx, `SELECT coalesce(from_state, ''), to_state, actor, reason FROM campaign_events WHERE campaign_id = $1 ORDER BY id`, id)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	for rows.Next() {
		var e event
		if err := rows.Scan(&e.From, &e.To, &e.Actor, &e.Reason); err != nil {
			t.Fatal(err)
		}
		r.Events = append(r.Events, e)
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	return r
}

// move runs one transition in its own transaction and commits on success.
func move(p *pgxpool.Pool, m Move) error {
	ctx := context.Background()
	tx, err := p.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	if err := Transition(ctx, tx, m); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// TestTransitionMatrixAgainstDatabase runs all 100 pairs through the guarded
// update. An allowed pair moves the row, bumps the version and writes one
// audit row. A pair outside the table changes nothing.
func TestTransitionMatrixAgainstDatabase(t *testing.T) {
	p := testPool(t)
	for _, from := range States() {
		for _, to := range States() {
			id := insertCampaign(t, p, from, 4)
			err := move(p, Move{ID: id, From: from, To: to, Version: 4, Actor: "marketer", Reason: "matrix"})
			got := load(t, p, id)
			if slices.Contains(allowed[from], to) {
				if err != nil {
					t.Errorf("%s -> %s: %v", from, to, err)
					continue
				}
				want := []event{{string(from), string(to), "marketer", "matrix"}}
				if got.State != to || got.Version != 5 || !slices.Equal(got.Events, want) {
					t.Errorf("%s -> %s: row %+v; want state %s, version 5, events %v", from, to, got, to, want)
				}
				continue
			}
			if !errors.Is(err, ErrInvalidTransition) {
				t.Errorf("%s -> %s: error %v, want ErrInvalidTransition", from, to, err)
			}
			if got.State != from || got.Version != 4 || len(got.Events) != 0 {
				t.Errorf("%s -> %s was rejected but changed the row: %+v", from, to, got)
			}
		}
	}
}

func TestTransitionConflicts(t *testing.T) {
	p := testPool(t)
	cases := []struct {
		name   string
		actual State
		m      Move
	}{
		{"stale version", InReview, Move{From: InReview, To: Rejected, Version: 6}},
		{"version from the future", InReview, Move{From: InReview, To: Rejected, Version: 8}},
		{"the campaign already moved on", Approved, Move{From: InReview, To: Rejected, Version: 7}},
	}
	for _, c := range cases {
		id := insertCampaign(t, p, c.actual, 7)
		c.m.ID, c.m.Actor = id, "marketer"
		if err := move(p, c.m); !errors.Is(err, ErrConflict) {
			t.Errorf("%s: error %v, want ErrConflict", c.name, err)
		}
		if got := load(t, p, id); got.State != c.actual || got.Version != 7 || len(got.Events) != 0 {
			t.Errorf("%s: a lost update changed the row: %+v", c.name, got)
		}
	}
	// A campaign that does not exist matches zero rows too.
	err := move(p, Move{ID: "00000000-0000-4000-8000-00000000dead", From: InReview, To: Rejected, Version: 0, Actor: "marketer"})
	if !errors.Is(err, ErrConflict) {
		t.Errorf("unknown campaign: error %v, want ErrConflict", err)
	}
}

// Two people act on the same review screen at once. Exactly one wins.
func TestConcurrentTransitionsOneWins(t *testing.T) {
	p := testPool(t)
	id := insertCampaign(t, p, InReview, 2)
	targets := []State{Approved, Rejected, Cancelled, Generating, Approved, Rejected, Cancelled, Generating}
	errs := make([]error, len(targets))
	start := make(chan struct{})
	var wg sync.WaitGroup
	for i, to := range targets {
		wg.Go(func() {
			<-start
			errs[i] = move(p, Move{ID: id, From: InReview, To: to, Version: 2, Actor: "marketer"})
		})
	}
	close(start)
	wg.Wait()

	winner := -1
	for i, err := range errs {
		switch {
		case err == nil && winner == -1:
			winner = i
		case err == nil:
			t.Errorf("transitions %d and %d both won", winner, i)
		case !errors.Is(err, ErrConflict):
			t.Errorf("loser %d: error %v, want ErrConflict", i, err)
		}
	}
	if winner == -1 {
		t.Fatal("no transition won")
	}
	got := load(t, p, id)
	if got.State != targets[winner] || got.Version != 3 || len(got.Events) != 1 {
		t.Errorf("row %+v; want state %s, version 3, one audit row", got, targets[winner])
	}
}

// The transition and its audit row belong to the caller's transaction, so
// approve and cancel can add their own writes atomically.
func TestTransitionRollsBackWithCaller(t *testing.T) {
	p := testPool(t)
	ctx := context.Background()
	id := insertCampaign(t, p, InReview, 0)
	tx, err := p.Begin(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if err := Transition(ctx, tx, Move{ID: id, From: InReview, To: Rejected, Version: 0, Actor: "marketer"}); err != nil {
		t.Fatal(err)
	}
	if err := tx.Rollback(ctx); err != nil {
		t.Fatal(err)
	}
	if got := load(t, p, id); got.State != InReview || got.Version != 0 || len(got.Events) != 0 {
		t.Errorf("after rollback: %+v", got)
	}
}

