package retry

import (
	"context"
	"errors"
	"io"
	"math/rand/v2"
	"net"
	"net/http"
	"strconv"
	"syscall"
	"time"
)

type Class string

const (
	Success     Class = "success"
	Timeout     Class = "timeout"
	RateLimited Class = "rate_limited"
	ServerError Class = "server_error"
	ConnRefused Class = "conn_refused"
	ConnReset   Class = "conn_reset"
	ClientError Class = "client_error"
)

func (c Class) Retryable() bool { return c != Success && c != ClientError }

type Result struct {
	Class      Class
	RetryAfter time.Duration
}

func Classify(resp *http.Response, err error, now time.Time) Result {
	if err != nil {
		var ne net.Error
		switch {
		case errors.Is(err, context.DeadlineExceeded), errors.As(err, &ne) && ne.Timeout():
			return Result{Class: Timeout}
		case errors.Is(err, syscall.ECONNREFUSED):
			return Result{Class: ConnRefused}
		case errors.Is(err, syscall.ECONNRESET), errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF):
			return Result{Class: ConnReset}
		}
		return Result{Class: ConnReset}
	}
	s := resp.StatusCode
	switch {
	case s >= 200 && s < 300:
		return Result{Class: Success}
	case s == 408:
		return Result{Class: Timeout}
	case s == 429:
		var d time.Duration
		h := resp.Header.Get("Retry-After")
		if f, err := strconv.ParseFloat(h, 64); err == nil {
			d = time.Duration(min(f, 60) * float64(time.Second))
		} else if t, err := http.ParseTime(h); err == nil {
			d = t.Sub(now)
		}
		return Result{Class: RateLimited, RetryAfter: max(0, min(d, 60*time.Second))}
	case s >= 500:
		return Result{Class: ServerError}
	}
	return Result{Class: ClientError}
}

func Backoff(attempt int, rng *rand.Rand) time.Duration {
	top := 60 * time.Second
	if attempt >= 0 && attempt < 6 {
		top = time.Second << attempt
	}
	return time.Duration(rng.Int64N(int64(top) + 1))
}
EOF
